

select v.position, v.name,
       array(select e.id from unnest(v.names) with ordinality as n(name, ord) join exercises e on e.name = n.name order by n.ord),
       array['Stretching / mobility (5 min)']
from (values
  (1, 'Legs', array['Leg Press', 'Leg Extension', 'Plank (sec)']),
  (2, 'Upper - Push', array['Dumbbell Bench Press', 'Machine Shoulder Press', 'Cable Triceps Pushdown', 'Push-ups']),
  (3, 'Legs', array['Leg Press', 'Leg Extension', 'Plank (sec)']),
  (4, 'Upper - Pull + Core', array['Lat Pulldown', 'Seated Cable Row', 'Dumbbell Biceps Curl', 'Cable Face Pull', 'Dead Bug']),
  (5, 'Legs', array['Leg Press', 'Leg Extension', 'Plank (sec)'])
) as v(position, name, names);


