  ('Power Day — Adapted', 'Today''s OTF template, inclines as written: pushes at 5-6-8%, all-outs at 10%+. This is a heavier knee load than we''ve done before — go by feel and back off incline (favor speed) if anything feels off.', '[{"sec": 120, "mode": "push", "incline": 5, "note": "PW @ 5%+", "block": "Block 1"}, {"sec": 60, "mode": "allout", "incline": 10, "note": "PW @ 10%+", "block": "Block 1"}, {"sec": 75, "mode": "walk", "incline": 1, "label": "Walk Recovery", "note": "Back to base, incline down", "block": "Block 1"}, {"sec": 60, "mode": "push", "incline": 6, "note": "PW @ 6%+", "block": "Block 1"}, {"sec": 60, "mode": "allout", "incline": 10, "note": "PW @ 10%+", "block": "Block 1"}, {"sec": 75, "mode": "walk", "incline": 1, "label": "Walk Recovery", "note": "Back to base", "block": "Block 1"}, {"sec": 30, "mode": "push", "incline": 8, "note": "PW @ 8%+", "block": "Block 1"}, {"sec": 60, "mode": "allout", "incline": 10, "note": "PW @ 10%+", "block": "Block 1"}, {"sec": 75, "mode": "walk", "incline": 1, "label": "Walk Recovery", "note": "Back to base", "block": "Block 1"}, {"sec": 60, "mode": "allout", "incline": 10, "note": "PW @ 10%+ (final)", "block": "Block 1"}, {"sec": 60, "mode": "walk", "incline": 1, "label": "Recovery", "note": "Easy walk, get to base when ready", "block": "Recovery"}, {"sec": 30, "mode": "push", "incline": 8, "note": "PW @ 8%+", "block": "Block 2"}, {"sec": 60, "mode": "allout", "incline": 10, "note": "PW @ 10%+", "block": "Block 2"}, {"sec": 75, "mode": "walk", "incline": 1, "label": "Walk Recovery", "note": "Back to base", "block": "Block 2"}, {"sec": 60, "mode": "push", "incline": 6, "note": "PW @ 6%+", "block": "Block 2"}, {"sec": 60, "mode": "allout", "incline": 10, "note": "PW @ 10%+", "block": "Block 2"}, {"sec": 75, "mode": "walk", "incline": 1, "label": "Walk Recovery", "note": "Back to base", "block": "Block 2"}, {"sec": 120, "mode": "push", "incline": 5, "note": "PW @ 5%+", "block": "Block 2"}, {"sec": 60, "mode": "allout", "incline": 10, "note": "PW @ 10%+", "block": "Block 2"}, {"sec": 75, "mode": "walk", "incline": 1, "label": "Walk Recovery", "note": "Back to base", "block": "Block 2"}, {"sec": 60, "mode": "allout", "incline": 10, "note": "PW @ 10%+ (final)", "block": "Block 2"}]'::jsonb);
